/* Authored English inquiry content; IDs, parameters, mathematical engines and notes are unchanged. */
'use strict';
(()=>{
  const I=MathStudioI18n,U=G7InquiryContent,C=G7InquiryCore;
  function unit(id,en){const u=U[id];I.registerTree(u,en);for(const [source,target] of [[u.question,en.title],[u.understanding,en.intro],[u.goal,en.rubric.join('; ')],[u.experiments,'Record at least three specified comparisons and identify the one condition changed each time.'],[u.dialogue,en.peer]])I.register([[source,target]]);if(en.cases)u.cases.forEach((c,i)=>I.register([[c[0],en.cases[i]]]));if(en.quick)I.register([[u.quick(C.calculate(id,C.defaults(id))).prompt,en.quick]]);if(en.followups)u.followups.forEach((f,i)=>{I.register([[f[0],en.followups[i][0]]]);const original=f[1];f[1]=r=>I.language==='en'?en.followups[i][1](r):original(r);});const meta=Inquiry.extraLabs[id];if(meta)I.registerTree(meta,{title:en.title,short:en.short,description:en.intro,question:en.conjecture,explain:en.hints[2]});}
  unit('number',{
    title:'Where should we meet to be fair?',short:'Meeting points on a number line',intro:'Three homes lie on a straight road. Measure each person’s distance to a meeting point, then compare minimising total travel with minimising the longest individual journey.',
    predict:'The homes are at −5, −1, and 7. Compare meeting at −1 and 1: which minimises total travel, and which minimises the longest journey? State both objectives first.',cases:['Meet at the middle home','Meet halfway between the outer homes','Move to the rightmost home','Symmetric homes'],
    conjecture:'“The point with the smallest total travel also makes the longest journey as short as possible.” Find an example with different answers.',hints:['Distance cannot be negative: −5 to −1 is 4 units. Subtract the smaller coordinate from the larger, or take the absolute difference.','List all three distances for each point, then calculate their sum and maximum. Do not consider only the home nearest you.','For three ordered homes, the middle home minimises the sum; the midpoint of the outer homes minimises the maximum. Examine how each distance changes as the meeting point moves.'],
    peer:'A classmate may choose the point closest to their own home. Explain your criterion using a table of all three distances.',transfer:'Homes lie at 0, 2, and 10. Find the meeting point minimising total travel and the one minimising the longest journey. Explain the difference to the residents.',model:['Total travel is least at 2: distances 2, 0, and 8 sum to 10.','The longest journey is least at 5: distances 5, 3, and 5 have maximum 5 and total 13.'],rubric:['Calculate three nonnegative distances correctly','Distinguish sum from maximum explicitly','Justify the chosen points through changes in distance'],misconception:'Treating coordinates as distances; assuming fairness has only one definition.',
    teacher:{prerequisites:'Number lines, signed numbers, and absolute value. Reasoning about optimal positions is an extension.',questions:['Does a negative coordinate imply a negative distance?','Can one plan be best under both criteria?','Whose journey increases when the point moves one unit?'],strategies:'Count units, tabulate distances, and compare increases and decreases.',exit:'How far apart are −3 and 5? Where is the midpoint minimising the longer journey?',exitAnswer:'They are 8 units apart; the midpoint is 1.'},extension:['Move the middle home while keeping the outer homes fixed. Which optimal point moves, and which stays fixed?','Compare (−5,−1,7) with (−5,4,7). The outer midpoint stays fixed, but the optimal point for total travel moves with the middle home.'],quick:'How far is home A from the current meeting point?',followups:[['How do signs enter a distance?',r=>`Home A is at ${r.params.h1}; the meeting point is ${r.params.a}. The signed change is ${r.params.a-r.params.h1}, while the distance is its absolute value, ${r.metrics.distances[0]}. Direction can be negative; distance cannot.`],['How do the two fairness criteria differ?',r=>`Total travel is ${r.metrics.total}; the longest journey is ${r.metrics.max}. The sum describes the collective burden; the maximum prioritises the furthest traveller. State the objective rather than saying only “fairest”.`],['How can we avoid checking every point?',r=>`The middle home is ${r.metrics.median}, and the outer midpoint is ${r.metrics.midpoint}. Between the outer homes, their two distances have constant sum. The third person’s distance is zero at their home, so the sum is least at the middle home.`]]});
  unit('powers',{
    title:'Do brackets always change the answer?',short:'Brackets and powers',intro:'A minus sign may be outside a power or part of its base. Expand as multiplication before investigating when the two expressions agree.',predict:'Predict whether −2² and (−2)² agree. Would your prediction change for cubes? Identify which part contains each minus sign.',cases:['Compare squares first','Change only the exponent','Try another even exponent','The zero boundary'],conjecture:'“Adding brackets always changes the answer.” Find counterexamples and state the conditions.',hints:['−2² means calculate 2×2, then take the opposite; (−2)² multiplies two negative factors.','Group results by odd and even exponent. Each pair of negative factors has positive product. Put a=0 in a separate row.','For a>0, both expressions are negative when n is odd; when n is even, one is negative and one positive. For a=0 and positive integer n, both are zero.'],peer:'A classmate says brackets always change the answer. Identify the omitted exponent cases and explain.',transfer:'Compare −5⁴ with (−5)⁴ and −5⁵ with (−5)⁵. Give an even-exponent example where both expressions agree.',model:['Fourth powers are −625 and 625; fifth powers are both −3125.','With a=0 and n=2, both are zero. Thus “different for even n” requires a>0.'],rubric:['Identify the base and the external minus sign','Include odd, even, and zero cases','Explain the factor structure rather than listing answers only'],misconception:'Reading the base of −aⁿ as −a; generalising from squares to all exponents.',teacher:{prerequisites:'Powers, multiplication sign rules, and order of operations.',questions:['Which minus sign participates in repeated multiplication?','Do equal results imply identical structures?','Does a=0 change the classification?'],strategies:'Expand factors, pair negative factors, and classify by parity.',exit:'Without calculating large numbers, compare −7⁶ and (−7)⁶.',exitAnswer:'They differ: left negative, right positive, because 7>0 and 6 is even.'},extension:['Design three pairs with different structures but equal results, including at least one zero base. State a rule classifying them.','Keep positive integer exponents. For nonzero a, use odd exponents; for a=0, every positive integer exponent gives agreement. Explain by pairing factors.'],quick:'What is the current bracketed power (−a)ⁿ?',followups:[['Where are the two minus signs?',r=>`For a=${r.params.a}, n=${r.params.n}, the left expression raises ${r.params.a} to power ${r.params.n}, then takes the opposite, giving ${r.metrics.left}. Each factor on the right is −${r.params.a}, giving ${r.metrics.right}.`],['Why does parity matter?',r=>`Pair the ${r.params.n} negative factors. ${r.params.n%2?'One negative factor remains':'No negative factor remains'}. A zero base gives zero directly. The current expressions ${r.metrics.equal?'agree':'differ'}.`],['Do a few cases prove the rule?',r=>`The case a=${r.params.a} is evidence, not every possible a. Explain the general rule using pairs of negative factors. Without calculating full values, determine the signs for n=5.`]]});
  unit('matches',{
    title:'Why can one matchstick picture have several formulas?',short:'Matchsticks and expressions',intro:'Place squares in one row, with one side shared by neighbours. Count the same picture in different ways. Solid segments are horizontal edges; dashed segments are vertical edges.',predict:'Draw one, two, and three joined squares. Predict how many new sticks each square adds. Do ten squares necessarily need forty sticks?',cases:['Start with one','Three joined squares','Same count, separate squares','The empty picture'],conjecture:'“Any n squares need 3n+1 sticks.” What arrangement and range of n were omitted?',hints:['The first square uses four sticks. Each further square shares an existing side and adds three.','Compare first-plus-additions; four per square minus shared sides; and n top, n bottom, n+1 vertical edges.','For n≥1 joined squares in one row, 4+3(n−1)=4n−(n−1)=3n+1. Separate squares need 4n; an empty picture has zero sticks and no first square.'],peer:'A classmate proposes 4n because each square has four sides. Identify the side counted twice.',transfer:'A row of joined squares uses 31 sticks. How many squares? How many sticks if they are all separated? Explain the difference.',model:['3n+1=31 gives n=10.','Separated squares need 40 sticks, nine more: each of nine shared sides must become two sides.'],rubric:['Connect expressions to the edges in the picture','Distinguish shared edges from double counting','State the arrangement and n≥1 condition'],misconception:'Counting shared edges twice; extending a positive-integer model to zero without checking.',teacher:{prerequisites:'Expressions, substitution, brackets, and the distributive law.',questions:['Where did your counting start?','What does −(n−1) count?','Which changed condition would invalidate the formula?'],strategies:'Count individually, track increments, group edges, and compare simplified formulas.',exit:'How many sticks form four joined squares? Give two counts.',exitAnswer:'13: 4+3×3 or 4×4−3; alternatively top 4, bottom 4, vertical 5.'},extension:['Split n squares into two disjoint rows, each containing at least one joined square. How does the formula change?','For row sizes k and n−k, the total is (3k+1)+(3(n−k)+1)=3n+2, for n≥2. Draw both rows to check.'],quick:'How many matchsticks are actually in the current picture?',followups:[['What does n−1 count?',r=>`Here n=${r.params.n}. ${r.params.n>0?`There are ${r.params.n-1} squares after the first and ${r.params.n-1} shared sides in a row.`:'There is no first square, so n−1 cannot count actual shared sides.'}`],['How do the formulas match the picture?',r=>`The three joined-row formulas give ${r.metrics.formulas[0]}, whereas the picture actually has ${r.metrics.total} sticks. ${r.params.joined&&r.params.n>0?'Match the terms to n top, n bottom, and n+1 vertical edges.':'This arrangement or empty picture does not satisfy the joined-row conditions.'}`],['Is agreement in a few cases enough?',r=>`n=${r.params.n} is one case. Generally, 4+3(n−1)=4+3n−3=3n+1 and 4n−(n−1)=4n−n+1=3n+1. Explain why shared edges justify these expressions.`]]});
  unit('magic',{
    title:'Why can a number trick predict the answer?',short:'Number tricks and cancellation',intro:'Start with x, add b, multiply by a, then subtract c times the original number. Investigate when the result no longer depends on x.',predict:'Does “add 2, multiply by 3, subtract three times the original number” always give 6? Try one mental example and explain your conjecture.',cases:['Start positive','Change only the starting number','Break the cancellation','Zero multipliers'],conjecture:'“Subtracting some multiple of the original number makes the result fixed.” Which two multipliers must match?',hints:['Record every step. Subtract a multiple of the original x, not of an intermediate result.','Expand a(x+b)−cx and collect the x terms.','a(x+b)−cx=(a−c)x+ab. If a=c, the x term vanishes; otherwise the result changes with x.'],peer:'A classmate treats three successful trials as proof. Ask which algebraic step guarantees the result for every starting number.',transfer:'Design a trick that adds first, multiplies next, and subtracts a multiple of the original number last, always producing −8. Explain.',model:['For example, add −4, multiply by 2, then subtract 2x.','2(x−4)−2x=2x−8−2x=−8 for every real x.'],rubric:['State unambiguous operations','Simplify every term and sign correctly','Explain the fixed answer through cancellation of x'],misconception:'Changing constants without checking cancellation; subtracting an intermediate value instead of the original number.',teacher:{prerequisites:'Distributive law, like terms, and polynomial addition.',questions:['Which number are you subtracting?','Which term carries the starting number’s influence?','Can substitution alone prove every real case?'],strategies:'Calculate stepwise, express algebraically, and compare coefficients.',exit:'Is 4(x+3)−3x constant?',exitAnswer:'No: it equals x+12 and still varies with x.'},extension:['Design two different rules that always give 12. Let a partner break the trick by changing one coefficient.','Choose a=c and ab=12, for example (3,4,3) or (2,6,2). Change c, then compare two starting numbers.'],quick:'What is the coefficient of x after simplifying the current rule?',followups:[['Which terms cancel?',r=>`Expansion gives ${r.params.a}x+(${r.metrics.constant})−(${r.params.c})x, with x coefficient ${r.metrics.coefficient}. ${r.metrics.invariant?'This coefficient is zero, so the starting number disappears.':'It is nonzero, so the result still depends on the starting number.'}`],['Does a negative starting number work?',r=>`The formula does not assume positive x. At x=−1 the result is ${-r.metrics.coefficient+r.metrics.constant}; compare this with ${r.metrics.value} for the current x=${r.params.x}.`],['Can I design a constant result of 12?',r=>`The current constant part ab=${r.metrics.constant}. For a constant 12, choose a=c=3 and b=4, giving (a−c)x+ab=0x+12. Other products ab=12 also work.`]]});
  unit('balance',{
    title:'Does doing the same thing to both sides preserve every solution?',short:'Equivalent equation transformations',intro:'Compare solution sets before and after an operation, and substitute a test x into both. Each transformation starts from the displayed original equation; operations do not accumulate invisibly.',predict:'Multiply both sides of 2x+3=11 by 2, then separately by 0. Predict the equations and whether their complete solution sets stay the same.',cases:['Add the same number','Multiply by a nonzero number','Multiply by zero','An inconsistent original equation','An identity'],conjecture:'“The same operation on both sides always preserves the solution set.” What goes wrong with multiplication or division by zero?',hints:['Find the original solutions and check them in the new equation; also check for additional solutions.','Multiplication by zero turns both sides into zero. Substitute x=0, which did not solve the original equation.','Equivalence requires identical solution sets. Nonzero multiplication can be reversed; zero multiplication usually loses restrictions. Division by zero is undefined. If the original is already an identity, zero multiplication may preserve all real solutions.'],peer:'A classmate says x=4 solves both equations, so they are equivalent. Test whether the new equation has extra solutions.',transfer:'Someone multiplies x=2 by zero to obtain 0=0, then answers x=9. Explain what the operation preserves and what it loses.',model:['The original solution 2 still satisfies 0=0, but so does 9 and every other real number.','The solution sets differ. The original equation still has only solution 2; multiplication by zero is not a reversible equivalent transformation.'],rubric:['Compare complete solution sets','Distinguish zero multiplication from undefined zero division','Support the explanation through substitution or inverse operations'],misconception:'Checking only an original solution; treating 0x=0 as x=0; treating division by zero as zero.',teacher:{prerequisites:'Equation solutions, equality properties, and substitution.',questions:['Does the new equation accept more x values?','Can the operation be reversed?','What if the original equation is already an identity?'],strategies:'Substitution counterexamples, solution-set comparison, and reversibility.',exit:'Does multiplying x=3 by −2 preserve equivalence? What about zero?',exitAnswer:'Multiplying by −2 is equivalent. Multiplying by zero gives all real solutions instead of the single original solution.'},extension:['If the original equation is an identity, does zero multiplication preserve its solution set? Refine “zero multiplication is always nonequivalent”.','Compare 0x+3=3 with 0x+3=5. The first has all real solutions, the second none. Both become 0=0 after zero multiplication, but only the first transformation preserves its solution set.'],quick:'Evaluate the left side a×0+b of the original equation.',followups:[['Does retaining an original solution establish equivalence?',r=>`The original solution set is ${r.metrics.original.kind==='one'?`x=${C.fmt(r.metrics.original.value)}`:r.metrics.original.kind==='all'?'all real numbers':'empty'}. You must also check whether the new equation has extra solutions.`],['What does substitution show?',r=>`For x=${r.params.candidate}, the original equation ${r.metrics.originalCheck?'holds':'fails'}, while the transformed equation ${!r.metrics.valid?'is undefined because of division by zero':r.metrics.transformedCheck?'holds':'fails'}. A value satisfying only the new equation disproves equivalence.`],['How do 0x=0 and 0x=5 differ?',r=>`Zero times every real number is zero. Thus 0x=0 always holds, while 0x=5 never holds. Here a=${r.params.a}, b=${r.params.b}, c=${r.params.c}; when a=0, compare b and c instead of dividing by a.`]]});
  unit('angles',{
    title:'Do longer drawn sides make a larger angle?',short:'Angle size and appearance',intro:'Rays extend indefinitely; the screen draws only part of each. Change the displayed lengths and overall orientation while observing the opening. The dashed ray marks the bisector.',predict:'Draw the sides of a 45° angle longer, then rotate the whole drawing. Will the angle increase? State what you would measure.',cases:['Short 45° sides','Change only the drawn length','Rotate the whole drawing','Short sides, larger opening'],conjecture:'“Longer sides in a drawing mean a larger angle.” Draw a counterexample.',hints:['Place the vertices together and align one ray. Does the other ray also align?','Change only one of drawn length, whole-figure rotation, or opening, and record the angle.','Angle size depends on the opening between rays, not their displayed lengths. Rotating both preserves their relative direction. The bisector divides the opening equally.'],peer:'A classmate judges the angle from the drawn sector’s area. Compare equal angles with different drawn lengths.',transfer:'Double both drawn sides of a 70° angle and rotate the drawing 90°. Find the new angle, each half-angle, and its supplement.',model:['The angle remains 70°; extension and rotation preserve its opening.','Each half is 35°; the supplement is 110°.'],rubric:['Distinguish length from angle','Explain invariance using alignment or relative direction','State valid complement and supplement conditions'],misconception:'Treating a drawn sector’s area as angle size; assuming changed orientation changes angle size.',teacher:{prerequisites:'Angles, degrees, complements, and supplements.',questions:['Does cropping a ray create a different angle?','Which control actually changes the opening?','Does an obtuse angle have a positive complement?'],strategies:'Overlay figures and vary length while fixing the opening.',exit:'What is a 30° angle after the whole drawing rotates 180°?',exitAnswer:'Still 30°: both rays rotate together and their relative opening stays fixed.'},extension:['Draw three different-looking figures with equal angles, then a shorter-sided figure with a larger angle. Justify by overlaying rays.','Control whole-figure rotation, displayed length, and opening separately. Only the opening changes the angle itself.'],quick:'What is each half of the current angle?',followups:[['Why can length not measure an angle?',r=>`Drawn lengths are ${r.params.l1} and ${r.params.l2}, but the opening remains ${r.params.angle}°. Extending a ray continues in the same direction without an additional turn.`],['What is each bisected angle?',r=>`${r.params.angle}°÷2=${r.metrics.bisector}°. The two parts sum to ${r.params.angle}°; bisecting an angle does not halve the lengths of its sides.`],['Does every angle have a positive complement?',r=>`90−${r.params.angle}=${90-r.params.angle}. ${r.params.angle<90?'This is positive and is the complement.':'This is not positive, so no positive complement exists.'} The supplement is 180−${r.params.angle}=${r.metrics.supplement}°.`]]});
  unit('parallels',{
    title:'Which angle relationships require parallel lines?',short:'Parallel lines and reasoning conditions',intro:'Two lines meet the same transversal. α and β are corresponding angles; α′ is vertically opposite α; γ is adjacent and supplementary to α. Only parts of the lines are drawn.',predict:'With parallel lines, α=β. Remove the parallel constraint: which equalities or supplementary relationships must still hold?',cases:['Keep lines parallel','Remove the constraint','Another nonparallel case','Free rotation, coincidentally parallel'],conjecture:'“Corresponding angles always agree.” State the necessary condition and identify relationships that do not require it.',hints:['Consider one intersection first: vertically opposite angles depend only on the two intersecting lines, not the other line.','Confirm parallelism before comparing α and β. Always α′=α and γ=180−α.','With parallelism, α=β, hence α′=β and γ+β=180°. Without it, these steps are unavailable. Measurements test examples; a general argument states its conditions.'],peer:'A classmate sees no intersection in the window and declares the lines parallel. Respond with angle relationships rather than appearance.',transfer:'Given parallel lines and α=65°, find β, α′, and γ with a reason for every step. Which answer is no longer fixed if parallelism is removed?',model:['β=65° by corresponding angles of parallel lines; α′=65° by vertically opposite angles; γ=115° by adjacent supplementary angles.','Without parallelism, β is not determined by α, but α′ and γ at the same intersection remain fixed.'],rubric:['Identify angle positions correctly','State the conditions needed by each relationship','Distinguish measurement evidence from deductive reasons'],misconception:'Assuming parallelism from appearance, then using the resulting angle equality to prove parallelism circularly.',teacher:{prerequisites:'Vertically opposite and adjacent supplementary angles; parallel-line properties and criteria.',questions:['Which step uses parallelism?','Which angles remain known without parallelism?','What could happen outside the window?'],strategies:'Label angles, list givens, give a reason per step, and remove conditions to test claims.',exit:'If two nonparallel lines meet a transversal, are vertically opposite angles still equal?',exitAnswer:'Yes, at each intersection. The property requires only two intersecting lines.'},extension:['Given only γ+β=180°, can you deduce parallelism? Give a reason for every step.','Adjacent supplementary angles give γ+α=180°. Compare to obtain α=β, then use equal corresponding angles to establish parallelism without assuming it first.'],quick:'Find the current angle γ.',followups:[['Which angles are alternate interior?',r=>`α′ and β lie between the lines on opposite sides of the transversal. They are ${r.params.alpha}° and ${r.params.beta}° and ${r.metrics.parallel?'agree because the lines are parallel':'do not agree'}.`],['Why are co-interior angles supplementary?',r=>`γ=180−α=${180-r.params.alpha}°. Adding β=${r.params.beta}° gives ${180-r.params.alpha+r.params.beta}°. This sum is 180° precisely when α=β is available.`],['Does no visible intersection imply parallelism?',r=>`Only segments of the lines are visible. Here α=${r.params.alpha}° and β=${r.params.beta}°. ${r.metrics.parallel?'Equal corresponding angles establish parallelism.':'The angles differ, so the extended lines intersect, possibly outside the window.'}`]]});
  unit('roots',{
    title:'How can we bracket √2 without a square-root key?',short:'Upper and lower square-root bounds',intro:'Find the side of a square with a specified area. Square a trial side and compare with the target; the subdivision setting gives bounds that can be checked by squaring.',predict:'For area 2, is the side between 1 and 2? Is 1.4 already exact?',cases:['Integer bounds','Tenths','Hundredths','A perfect square','Zero area'],conjecture:'“A calculator’s displayed decimal is the exact square root.” Test it by squaring.',hints:['Sides 1 and 2 give areas 1 and 4. Increasing a nonnegative side increases its square.','Compare 1.4² and 1.5² with the target, then subdivide the interval.','1.41²=1.9881 and 1.42²=2.0164, so 1.41<√2<1.42. These are strict bounds, not equality. Finitely many refinements cannot prove a decimal never repeats.'],peer:'A classmate writes √2=1.41. Use squared comparisons to explain which symbol should replace the equals sign.',transfer:'Use 2.23² and 2.24² to bracket √5. Distinguish √5 from the solutions of x²=5.',model:['2.23²=4.9729 and 2.24²=5.0176, so 2.23<√5<2.24.','√5 is the nonnegative principal value; x²=5 has solutions ±√5.'],rubric:['Check both bounds by squaring','Distinguish approximation from exact equality','Do not treat finite computation as a proof of irrationality'],misconception:'Writing √a as ±; treating a truncated decimal as exact; using a negative side in the area model.',teacher:{prerequisites:'Squares, principal square roots, and decimal arithmetic.',questions:['What shows that a guess is too high?','Does narrowing an interval find an exact value?','When can a perfect-square case stop?'],strategies:'Trial values, maintained bounds, successive subdivision, and checking by squaring.',exit:'Given 1.7²=2.89 and 1.8²=3.24, where is √3?',exitAnswer:'1.7<√3<1.8 because squaring is increasing for nonnegative numbers.'},extension:['Bracket √3, √5, and √9 with width at most 0.01. Which can be an exact point, and which remain intervals?','Use hundredth bounds and verify squares; √9=3. A narrow interval does not prove irrationality or make its midpoint exact.'],quick:'What is the currently displayed lower square-root bound?',followups:[['Is this guess too large or too small?',r=>`${r.params.side}²=${r.metrics.area}; target ${r.params.target}. ${r.metrics.comparison<0?'The area and nonnegative side are too small.':r.metrics.comparison>0?'The area and nonnegative side are too large.':'They agree exactly, so this side is exact.'}`],['How can we verify the bounds?',r=>`The lower bound is ${r.metrics.lower} and upper bound ${r.metrics.upper}. Square both and compare with ${r.params.target}. The activity checks decimal boundaries with scaled integers to avoid false equalities caused by rounding.`],['Why not choose a negative square root as the side?',r=>`The area is ${r.params.target}. The equation x²=${r.params.target} concerns both signed roots, whereas √${r.params.target} denotes the nonnegative principal root and a physical side cannot be negative. At area zero, only 0 remains.`]]});
  unit('routes',{
    title:'Does the same endpoint imply the same distance travelled?',short:'Coordinate routes and distance',intro:'Each instruction moves one grid unit horizontally or vertically. Build a route with the direction buttons. Changing the start translates the same instruction sequence; at most 120 steps are allowed.',predict:'Travel from (−2,1) to (3,4), first right then up, or by a detour. Predict whether endpoints and total distances agree.',cases:['Right, then up','Up, then right','Add a return trip','Return to the starting point'],conjecture:'“Routes sharing an endpoint have equal lengths.” Find a counterexample and investigate shortest routes.',hints:['Right adds 1 to x, left subtracts 1; up adds 1 to y, down subtracts 1. Every instruction adds one unit of travel.','A left-right pair cancels in coordinate change but adds two travel units. Separate net movement from step count.','At least the absolute horizontal difference plus the absolute vertical difference is needed. On an unobstructed grid, avoiding reverse steps attains this bound; different orders may be equally short.'],peer:'A classmate adds final coordinates to find travel distance. Test this with a route returning to its start.',transfer:'From (−1,−2) to (2,2), give two shortest instruction sequences and a route to the same endpoint that is two units longer.',model:['The minimum is |2−(−1)|+|2−(−2)|=3+4=7. RRRUUUU and UUUURRR both work.','Prefix LR to RRRUUUU: nine steps still end at (2,2).'],rubric:['Match coordinates to instructions','Separate signed change from accumulated travel','Justify the lower bound and exhibit an attaining route'],misconception:'Confusing displacement with travel; using straight-line distance despite the grid restriction.',teacher:{prerequisites:'Ordered pairs, translation, and absolute value.',questions:['What does an out-and-back step change?','Why can one fewer step not reach the target?','Does changing instruction order change the endpoint?'],strategies:'Step tables, route drawings, direction counts, and lower bounds with constructions.',exit:'Three steps right then one left: what is the horizontal change, and the distance travelled?',exitAnswer:'Horizontal change +2; travel distance 4 units.'},extension:['How many shortest grid routes go from (0,0) to (2,2)? List them systematically without repetition.','Every shortest route has two R and two U. Classify by the positions of R: RRUU, RURU, RUUR, URRU, URUR, UURR, six routes.'],quick:'How many grid units has the current route travelled?',followups:[['How do coordinate change and travel differ?',r=>`Net translation is (${r.metrics.dx},${r.metrics.dy}), while travel is ${r.metrics.length} units. Opposite instructions cancel in coordinate change, but travelled units remain.`],['Why is this a shortest-distance lower bound?',r=>`The endpoints require ${Math.abs(r.params.tx-r.params.sx)} horizontal and ${Math.abs(r.params.ty-r.params.sy)} vertical units. Each step changes only one coordinate, so at least ${r.metrics.minimum} steps are needed.`],['Is a shortest route unique?',r=>`The target is (${r.params.tx},${r.params.ty}). If both coordinates must change, reorder horizontal and vertical steps while retaining ${r.metrics.minimum} steps. A single-direction journey has no such ordering choice.`]]});
  unit('tickets',{
    title:'Do ticket count and revenue determine the sales?',short:'Ticket data and simultaneous equations',intro:'x and y count tickets of types A and B. Find values satisfying both equalities, then check that ticket counts are nonnegative integers.',predict:'Ten tickets cost 2 dollars for A or 5 dollars for B, with revenue 32 dollars. Can sales be reconstructed? What if revenue changes to 31?',cases:['Feasible data','A noninteger solution','Revenue outside the possible range','Equal ticket prices'],conjecture:'“Two equations always give one usable answer.” Distinguish insufficient from contradictory information.',hints:['With ten tickets, enumerate x=0,1,…,10 and y=10−x, then check revenue.','Use the total-count equation to eliminate one unknown. After solving, ask whether fractional or negative ticket counts are possible.','Equal prices may make the revenue equation a multiple of the count equation, adding no information. Infinitely many real solutions need not mean infinitely many feasible nonnegative integer allocations.'],peer:'A classmate rounds 3.67 tickets to four. Substitute the rounded counts into both original conditions.',transfer:'A tickets cost 3 dollars, B tickets 7 dollars, and eight tickets are sold. Are revenues of 40 and 41 dollars feasible?',model:['3(8−y)+7y=40 gives y=4 and x=4, which is feasible.','Revenue 41 gives y=17/4, not an integer. Rounding does not preserve the original data.'],rubric:['Construct both equalities correctly','Check both equations and nonnegative integer restrictions','Distinguish contradiction, insufficient information, and infeasible real solutions'],misconception:'Assuming two equations always yield one solution; approximating ticket counts.',teacher:{prerequisites:'Linear systems in two variables, substitution, and elimination.',questions:['Which datum adds a new restriction?','Does a fractional answer necessarily mean a calculation error?','Do equal prices identify ticket types?'],strategies:'Enumeration, elimination, revenue bounds, and substitution checks.',exit:'Five tickets all cost 2 dollars. Can their revenue be 11 dollars?',exitAnswer:'No. Every allocation of types must give 10 dollars.'},extension:['With equal ticket prices, what extra datum would uniquely determine the counts? Design and check an example.','For example, A exceeds B by two tickets. With x+y=10, this gives x=6, y=4. The new restriction must be independent, not another statement of the same revenue.'],quick:'How many nonnegative integer ticket allocations are currently feasible?',followups:[['How do we eliminate one unknown?',r=>`From x+y=${r.params.total}, x=${r.params.total}−y. The revenue equation becomes (${r.params.priceB}−${r.params.priceA})y=${r.params.revenue}−${r.params.priceA*r.params.total}.`],['Is this real solution usable for tickets?',r=>`There are ${r.metrics.pairs.length} nonnegative integer allocations. ${r.metrics.real==='one'?`Computed x=${C.fmt(r.metrics.x)} and y=${C.fmt(r.metrics.y)} must both be nonnegative integers.`:'With equal prices, first check whether revenue equals price × total count.'}`],['Why do equal prices prevent unique reconstruction?',r=>`If both tickets cost ${r.params.priceA}, revenue records only the total count. For ${r.params.total} tickets there are ${r.params.total+1} nonnegative integer allocations; all are feasible only if revenue agrees.`]]});
  unit('tariffs',{
    title:'Is the cheaper plan necessarily usable?',short:'Tariffs, budgets, and feasible ranges',intro:'A costs 2 dollars per use. B has a fixed fee plus a per-use rate. The class also has a minimum required number of uses and a budget. Compare prices, then combine all restrictions.',predict:'For B with fixed fee 24 and rate 1.2, budget 70, and at least 20 uses, compare 30, 36, and 40 uses. Is the cheaper plan always affordable?',cases:['Equal price, both feasible','Only B fits the budget','Cheaper but still over budget','Identical prices for all uses'],conjecture:'“Choosing the cheaper plan completes the decision.” Could minimum usage and budget change the recommendation?',hints:['Calculate A=2n and B=F+rn. State minimum usage and budget separately.','Find each plan’s feasible integer interval. A decimal upper bound permits only integers no larger than it.','With defaults, A permits 20–35 uses and B 20–38. Prices agree at 30. At 40, B is cheaper but both exceed the budget.'],peer:'A classmate compares only per-use rates. Include fixed fees, budget, and minimum need in the recommendation.',transfer:'A costs 2 per use. B has fee 10 and rate 1. With budget 25 and at least eight uses, find both feasible integer intervals and recommend plans for nine and fourteen uses.',model:['A permits integers 8≤n≤12; B permits integers 8≤n≤15.','At nine uses, A=18 and B=19, so choose A. At fourteen, A=28 exceeds budget while B=24 is feasible.'],rubric:['State costs and contextual restrictions together','Handle inclusive endpoints and integer bounds correctly','Condition recommendations on usage and feasibility'],misconception:'Comparing rates only; treating negative or fractional equal-price solutions as actual usage.',teacher:{prerequisites:'Linear inequalities, their systems, and number lines.',questions:['How do “cheaper” and “affordable” differ?','Which endpoints are included?','What if the fixed fee exceeds the budget?'],strategies:'Solve each restriction, intersect sets, compare number lines, and test boundaries.',exit:'If n≤12.5 and n is an integer, how many uses are allowed at most?',exitAnswer:'12 uses; 13 violates the upper bound.'},extension:['Keep rates fixed and lower the budget. Find cases with both plans feasible, only one feasible, and neither feasible.','Fix 36 uses and minimum 20. A=72 and B=67.2. Compare budgets 80, 70, and 60, including equality boundaries.'],quick:'Under the current budget, how many uses of A are affordable at most, ignoring the minimum?',followups:[['Does cheaper mean feasible?',r=>`A=${C.fmt(r.metrics.costA)}, B=${C.fmt(r.metrics.costB)}, budget ${r.params.budget}, minimum ${r.params.minimum} uses. A is ${r.metrics.feasibleA?'feasible':'infeasible'}; B is ${r.metrics.feasibleB?'feasible':'infeasible'}. Every restriction must hold.`],['How do we handle a decimal upper bound?',r=>`For A, n≤${C.fmt(r.params.budget/2)}, so the maximum integer is ${r.metrics.maxA}. B permits at most ${r.metrics.maxB} uses. An upper bound below the minimum ${r.params.minimum} leaves no feasible usage.`],['Does an equal-price point always exist?',r=>`The equation is (2−${r.params.rate})n=${r.params.fixed}. ${r.params.rate===2?(r.params.fixed===0?'Both sides vanish; every usage gives equal prices.':'The left is always zero and the right is positive, so no equality exists.'):`The real solution n=${C.fmt(r.metrics.threshold)} still needs nonnegative and integer checks.`}`]]});
  unit('sampling',{
    title:'Do more respondents necessarily make a survey better?',short:'Sampling and charts',intro:'This is a synthetic school, not a real survey. Of 200 pupils, 100 choose A. In one 40-pupil club, 36 choose A. Sample from the school or only from the club; each sample visits each person at most once.',predict:'Would surveying all forty club members be closer to the whole-school 50% than randomly sampling twenty pupils? State what affects representativeness.',cases:['Random school sample of 20','Same size, different sampling frame','Increase club sample to 40','Increase school sample to 40'],conjecture:'“More respondents always bring the result closer to the school proportion.” Refine this using sampling method and repeated samples.',hints:['Calculate frequency ÷ sample size. Separate who was surveyed from how many were surveyed.','A fixed seed reproduces the sample. Try the next seed. The display also shows thirty samples starting from this seed; inspect variation rather than selecting one attractive result.','All forty club members reveal that club’s 90%, not the school’s 50%. Larger random school samples usually reduce variation but do not guarantee that each individual sample is closer to 50%.'],peer:'A classmate says more friends from the same club will represent the school. Distinguish sampling frame from target population.',transfer:'A survey asks forty basketball-team pupils about the year group’s favourite lunch. Improve the plan and explain why no sample result can be guaranteed to equal the population proportion.',model:['Randomly sample from the whole year-group list, giving pupils from different classes and interests a chance. Record nonresponse.','Sampling still varies. More respondents neither guarantee a more accurate individual result nor automatically correct selection bias.'],rubric:['Distinguish sample from population','Compare methods at the same sample size','Retain variation and the synthetic-data limitation'],misconception:'Assuming large samples must be representative; selecting the closest trial; ignoring truncated axes.',teacher:{prerequisites:'Frequency, relative frequency, percentages, and bar charts.',questions:['Which one condition changed between the two trials?','Who was excluded?','Can one worse resample disprove an overall tendency?'],strategies:'Controlled comparisons, repeated sampling, sample composition, and axis-scale checks.',exit:'Surveying every club member gives 90%. Can we claim the whole school is 90%?',exitAnswer:'No. The surveyed population is the club; this synthetic school has a whole-school proportion of 50%.'},extension:['With a fixed method, compare thirty samples of size 10 and 40 from the same initial seed, then switch to club-only sampling.','Compare the range and location of the thirty percentages. One seed sequence describes these trials, not all possible resamples. Bias and variation are different issues.'],quick:'How many people in the current sample did not choose A?',followups:[['How is this percentage calculated?',r=>`${r.metrics.count} choosing A ÷ sample size ${r.params.size} × 100% = ${C.fmt(r.metrics.percent)}%. The denominator is the people sampled, not all 200 pupils.`],['Why can a larger sample remain biased?',r=>`This trial ${r.params.method==='club'?'surveys only the club':'samples from the school'}. The club is 90% A and the school 50%; more respondents from one group do not recover missing groups. The thirty-trial average ${C.fmt(r.metrics.average)}% describes only this sequence.`],['Does changing the chart scale change the data?',r=>`The sample remains ${C.fmt(r.metrics.percent)}% A, and the school 50%. Starting the vertical axis at ${r.params.baseline}% changes visual lengths only. Mark truncation and off-window values; bar length is not the full proportion on a truncated axis.`]]});
  const generic={
    linear:{question:'How do changes in a graph correspond to fixed and variable model quantities?',understanding:'Slope gives change per input unit; the intercept records the initial quantity.',goal:'Model a context with a linear function and explain its parameters and limits.',predict:'Fix b=1 and change k. Predict the stationary point, then what happens when k becomes negative.',experiments:'With b fixed, compare positive, zero, and negative k. Then fix k and change b. Change one parameter at a time and save at least three cases.',dialogue:'Someone claims a larger k gives a larger y for every x. Find a counterexample and state the required condition on x.',transfer:'A tank starts with 120 L and drains at 8 L per minute. Write V(t), its time domain, and its volume at ten minutes. Explain both intercepts.',model:['V(t)=120−8t, 0≤t≤15.','V(10)=40 L. The vertical intercept 120 is initial volume; the horizontal intercept 15 is the emptying time.'],rubric:['Include negative rate and initial volume','State the correct domain and units','Interpret both intercepts in context'],misconception:'Confusing intercept with slope; treating negative volumes beyond the time domain as physical results.'},
    pythagoras:{question:'Which quantities scale together when a shape is enlarged?',understanding:'Pythagoras’ theorem connects right-triangle sides; length and squared length have different scale factors.',goal:'Select a right triangle for a measurement problem and check its scale.',predict:'If a and b both double, predict the factors for c and c², with a reason.',experiments:'Save (3,4), (6,8), and a pair of noninteger legs. Distinguish the exact squared relation from approximate side lengths.',dialogue:'Compare “the hypotenuse doubles” with “the square of the hypotenuse doubles”. Which holds?',transfer:'A ramp has horizontal run 4 m and rise 1.5 m. Find the handrail length to 0.01 m. Keeping its slope, scale both dimensions by 1.5. Find the new handrail length.',model:['Length = √(4²+1.5²)=√18.25≈4.27 m.','Scaling by 1.5 gives 1.5√18.25≈6.41 m. Calculate from the unrounded value.'],rubric:['Identify perpendicular horizontal and vertical legs','Use the squared sum and a reasonable approximation','Explain the new length through proportional scaling'],misconception:'Adding the legs; treating a displayed approximation as an exact proof.'},
    exponential:{question:'How do fixed increments and fixed multipliers produce different long-term change?',understanding:'Exponential change preserves ratios. The base controls growth or decay, but does not determine the initial value.',goal:'Model repeated proportional change and identify fixed points and assumptions.',predict:'Predict the direction of graphs for a=0.5, 1, and 2, and their common output at x=0.',experiments:'Save a=0.5, 1, and 2, comparing x=−1,0,1,2. Classify a=1 separately as a constant function.',dialogue:'Compare “decrease by 20% each round” and “decrease by 20 each round” for two rounds from the same initial value.',transfer:'A filtration model retains 80% of the previous round’s impurity, initially 100 units. Model round n, find round 3, and explain why no finite round gives exactly zero.',model:['M(n)=100×0.8ⁿ for nonnegative integer n; M(3)=51.2.','A positive base to any finite power remains positive. Real measurements have precision and model limits; the model does not guarantee permanent detectability.'],rubric:['Apply the multiplier to the previous round','Find 51.2 and state the domain of n','Distinguish mathematical positivity from measurement limits'],misconception:'Treating percentage change as a fixed amount; omitting the initial case n=0.'},
    trig:{question:'Can position and direction describe periodic motion together?',understanding:'Unit-circle coordinates connect sine and cosine values, signs, and periods.',goal:'Explain signs with the unit circle and model a periodic height.',predict:'Compare sine and cosine at 30° and 150°. Which agree, and which have opposite signs?',experiments:'Save 30°,150°,210°,330°. Compare quadrants, then compare 0° and 360°.',dialogue:'Someone takes only the positive root when using sin²θ+cos²θ=1 to find cosine. What additional information is needed?',transfer:'A Ferris wheel has radius 5 m, centre height 6 m, and period 40 seconds. Starting at the rightmost point, it rotates anticlockwise at constant speed. Model height h(t) and find heights at 10 and 30 seconds.',model:['h(t)=6+5sin(πt/20), with t in seconds and angle in radians.','h(10)=11 m and h(30)=1 m. Initially h(0)=6 m and height is increasing.'],rubric:['Match initial position and direction','Use amplitude 5, centre 6, and period 40','Give correct heights and units'],misconception:'Ignoring quadrant after using a squared identity; overlooking initial phase.'},
    sets:{question:'How should a person belonging to two groups be counted?',understanding:'Intersection records shared elements; union counts each element once.',goal:'Form sets from a context and verify category counts against the total.',predict:'If A and B each have three elements, must their union contain six? Predict first.',experiments:'Save intersection, union, and difference. Use shading to explain element 3 in each operation.',dialogue:'Explain why the intersection is subtracted once using elements rather than only quoting the formula.',transfer:'Of 40 pupils, 24 choose art, 21 science, and 10 both. Find art only, science only, both, and neither, and check the total.',model:['Art only 14; science only 11; both 10; neither 5.','Union =24+21−10=35. The four disjoint categories sum to 14+11+10+5=40.'],rubric:['Use four disjoint categories','Calculate every category correctly','Verify their sum is 40'],misconception:'Subtracting the intersection twice; interpreting “at least one” as “exactly one”.'},
    triangle:{question:'How can boundary cases improve a conjecture?',understanding:'Triangle existence requires a strict inequality; equality gives a degenerate collinear figure.',goal:'Check whether a construction is possible, give the full range, and explain boundaries.',predict:'Fix a=4 and b=5. Predict whether c=1,5,9 forms a triangle.',experiments:'With a=4,b=5, test c=0.5,1,1.5,8.5,9,9.5. Save the boundary and values on both sides.',dialogue:'Compare “sum at least the third side” and “sum greater than the third side”. Describe the equality case.',transfer:'Two craft sticks are 5 cm and 8 cm. List every possible integer third side. Which choices give an isosceles triangle?',model:['3<c<13, so integer lengths are 4 through 12 cm.','Isosceles choices require c=5 or 8, both inside the valid range.'],rubric:['Check both difference and sum bounds','List the complete integer set','Verify both isosceles and feasibility conditions'],misconception:'Checking only the upper bound; counting a collinear figure as a triangle.'},
    area:{question:'How far can a diagram explain an algebraic formula?',understanding:'Area partition explains distribution, but no block may be omitted. The diagram’s domain differs from a general identity’s domain.',goal:'Apply multiplication formulas to area change and explain them algebraically.',predict:'For a=b=2, predict whether (x+2)²−x² is always 4.',experiments:'Fix a=b=2 and save x=2,4,6. Then use unequal a,b and inspect both rectangles.',dialogue:'One partner points to the diagram while the other reads the expression. Does every term have a corresponding block?',transfer:'A rectangular garden has length x+3 and width x. Increase both dimensions by 2 m. Find the added area for x>0 and explain each term to the gardener.',model:['New area =(x+5)(x+2); old area =x(x+3).','Subtract to obtain 4x+10 m². Interpret strips and the corner block, or check by distribution.'],rubric:['State new and old dimensions and areas correctly','Simplify to 4x+10','Connect algebraic terms to areas and units'],misconception:'Omitting cross terms; using a positive-length picture alone to prove negative-input cases.'},
    outlier:{question:'Can one dataset support different descriptions of a typical value?',understanding:'A statistic’s suitability depends on purpose. The mean and median respond differently to extremes.',goal:'Give an evidence-based description for an audience while preserving important differences.',predict:'Change the fifth value from 8 to 40. Will the mean and median both increase greatly?',experiments:'Save fifth values 0,6,8,40. Sort before finding each median.',dialogue:'One partner argues for the mean and the other for the median. State the question being answered, then compare strengths.',transfer:'Five commute times are 10,12,13,15,60 minutes. Choose a typical time for a school magazine, with reasons, and provide another statistic that keeps the long commute visible.',model:['Mean 22 minutes, median 13; most values lie from 10 to 15.','The median 13 may describe a typical commute, with maximum 60 or range 10–60 retaining the long journey. Other justified choices are acceptable.'],rubric:['Calculate mean and median correctly','Match the chosen statistic to the descriptive purpose','Retain the extreme and relevant limitations'],misconception:'Assuming one statistic is always best; removing data merely to improve the mean.'},
    quadratic:{question:'Under what conditions does a solving shortcut remain reliable?',understanding:'Quadratic signs depend on roots, leading coefficient, and repeated-root cases.',goal:'Check factor signs against graphs and contextual solution domains.',predict:'Predict how changing a from 1 to −1 affects f(x)≤0. What if the roots coincide?',experiments:'Fix roots −2 and 3 and save a=1 and −1. Then make the roots equal, and finally try a=0.',dialogue:'One partner uses a graph, another factor signs. Check repeated roots, equality, and a=0 together.',transfer:'A net-return model is P(x)=−(x−2)(x−8), with activity scale 0≤x≤10. Find the non-loss range. If x must be integer, list the choices.',model:['No loss requires P(x)≥0, equivalently (x−2)(x−8)≤0.','The solution [2,8] lies within the contextual domain. Integer choices are 2,3,4,5,6,7,8.'],rubric:['Translate no loss as ≥0','Handle the minus sign and endpoints','Intersect with contextual and integer restrictions'],misconception:'Always choosing between roots; omitting sign reversal or repeated-root cases.'}
  };
  for(const [id,en] of Object.entries(generic))I.registerTree(Inquiry.units[id],en);
  const mathWords={
    '住宅':'Home','集合點':'Meeting point','總路程':'Total travel','最遠路程':'Longest journey','單位':'units','逐個分開計算':'Count separately','重複計了的共邊':'Double-counted shared sides','實際火柴數':'Actual sticks','先加':'Add first','再乘':'Then multiply','最後減':'Finally subtract','原式解集':'Original solution set','變形後解集':'Transformed solution set','原式':'Original equation','變形後':'Transformed equation','全體實數':'All real numbers','空集':'Empty set','不能除以 0':'Cannot divide by zero','此操作沒有定義':'This operation is undefined','不可檢查':'Cannot check','不成立':'False','成立':'True','代入':'Substitute','角平分後':'After bisection','正角的餘角':'Positive complement','不存在正角的餘角':'No positive complement','開口':'Opening','補角':'Supplement','上交點的對頂角':'Vertically opposite angles at the upper intersection','同位角 α、β':'Corresponding angles α, β','內錯角 α′、β':'Alternate interior angles α′, β','同旁內角 γ、β':'Co-interior angles γ, β','試驗面積':'Trial area','與目標比較':'Comparison with target','可核對的界':'Verifiable bounds','目前終點':'Current endpoint','橫、縱平移量':'Horizontal and vertical translation','已走路程':'Travelled distance','至目標的最短格線路程':'Shortest grid route to target','張數條件':'Ticket-count condition','收入條件':'Revenue condition','實數方程組':'Real-valued system','無限多組實數解':'Infinitely many real solutions','無解':'No solution','非負整數可行組合':'Feasible nonnegative integer allocations','（非整數時顯示近似值）':'(approximate display for noninteger values)','沒有':'None','A：每次 2 元':'A: 2 dollars per use','B：固定費＋按次':'B: fee plus per-use cost','不符合最低用量或預算':'Fails minimum usage or budget','可行':'Feasible','A 可行範圍':'A feasible range','B 可行範圍':'B feasible range','同價條件':'Equal-price condition','沒有可行整數用量':'No feasible integer usage','所有用量同價':'Same price at every usage','沒有同價用量':'No equal-price usage','同價解為負數，不在情境中':'Equal-price solution is negative and outside the context','（非整數，實際用量沒有同價點）':'(noninteger; no actual equal-price usage)','n 為整數':'n is an integer','合成全校資料':'Synthetic school data','特定小組':'Specified club','本次樣本':'Current sample','樣本編號':'Sample identifiers','30 次重抽的 A 百分比':'A percentages in 30 resamples','30 次平均':'30-sample average','200 人；A：100 人，B：100 人（A 佔 50%）':'200 pupils; A:100, B:100 (50% A)','40 人；A：36 人，B：4 人（A 佔 90%）':'40 pupils; A:36, B:4 (90% A)','A 頻率':'A relative frequency','（不保證每次較大樣本都更接近 50%）':'(larger samples are not guaranteed closer to 50% in every trial)','路線 U上 D下 L左 R右':'Route U up, D down, L left, R right','人':'people','元':'dollars','格':'grid units','支':'sticks','、':', ','；':'; ','，':', ','：':': ','（':' (', '）':')'
  };
  function authoredMath(value){let out=value;for(const [zh,en] of Object.entries(mathWords).sort((a,b)=>b[0].length-a[0].length))out=out.split(zh).join(en);return out;}
  const originalCalculate=C.calculate,originalSnapshot=C.snapshot;
  const controlNames={number:['Home A position','Home B position','Home C position','Meeting-point position'],powers:['Nonnegative a','Positive integer exponent n'],matches:['Number of squares n','Arrangement'],magic:['Starting number x','Outside multiplier a','Number added first b','Final original-number multiplier c'],balance:['Original coefficient a of x','Original left constant b','Original right constant c','Operation on both sides','Operation operand','Test value x'],angles:['Opening (degrees)','First ray’s displayed length','Second ray’s displayed length','Whole-drawing rotation (degrees)'],parallels:['Upper corresponding angle α (degrees)','Lower corresponding angle β (degrees)','Line constraint'],roots:['Target square area','Decimal places of subdivision','Trial side'],routes:['Start x-coordinate','Start y-coordinate','Target x-coordinate','Target y-coordinate'],tickets:['A ticket price (dollars)','B ticket price (dollars)','Total tickets sold','Total revenue (dollars)'],tariffs:['B fixed fee (dollars)','B per-use rate (dollars)','Number of uses','Minimum required uses','Budget (dollars)'],sampling:['Sample size','Sampling frame','Experiment seed','Chart vertical-axis start']};
  for(const [id,labels] of Object.entries(controlNames))Object.values(C.definitions[id].controls).forEach((spec,i)=>I.register([[spec.label,labels[i]]]));
  I.register({'排成一列，共用相鄰邊':'One row with shared adjacent sides','每個正方形分開':'Separate squares','保持平行（β 跟隨 α）':'Keep parallel (β follows α)','自由轉動':'Free rotation','從全校隨機抽樣':'Random sample from the school','只訪問某個課外活動小組':'Sample only one club','40%（截斷軸）':'40% (truncated axis)','減':'Subtract','除':'Divide'});
  I.template('{0}（滑桿）','{0} (slider)');I.template('{0}（數值）','{0} (number)');
  function dynamic(id,r){const p=r.params,m=r.metrics;let summary='';
    if(id==='number')summary=`Meeting point ${p.a}: total travel ${C.fmt(m.total)}; longest journey ${C.fmt(m.max)}.`;
    if(id==='powers')summary=`a=${p.a}, n=${p.n}: the expressions ${m.equal?'agree':'differ'}.`;
    if(id==='matches')summary=`${p.n} ${p.joined?'joined':'separate'} squares need ${m.total} sticks. ${p.n===0?'The empty picture has zero sticks; 3n+1 does not apply at n=0.':p.joined?'The shared-edge formula applies for n≥1.':'Separate squares use 4n; the shared-edge formula does not apply.'}`;
    if(id==='magic')summary=`${p.a}(x+(${p.b}))−(${p.c})x=(${m.coefficient})x+(${m.constant}); current result ${m.value}.`;
    if(id==='balance')summary=!m.valid?'Division by zero is undefined; no transformed equation is constructed.':`The solution sets ${m.equivalent?'agree':'differ'}. ${p.operation==='multiply'&&p.operand===0?'Zero multiplication gives 0=0; compare the original solution set to decide equivalence.':''}`;
    if(id==='angles')summary=`Displayed lengths ${p.l1}, ${p.l2}; rotation ${p.rotation}°; the angle remains ${p.angle}°.`;
    if(id==='parallels')summary=`The lines are ${m.parallel?'parallel':'not parallel'}. Vertically opposite angles are equal regardless of this parallel condition.`;
    if(id==='roots')summary=m.exact?`√${p.target}=${m.lower} exactly.`:`${m.lower}<√${p.target}<${m.upper}; interval width ${C.fmt(m.upper-m.lower)}.`;
    if(id==='routes')summary=`${m.reached?'Target reached':'Target not yet reached'}; travelled ${m.length} grid units; endpoint (${m.x},${m.y}).`;
    if(id==='tickets')summary=`There are ${m.pairs.length} feasible ticket allocations. ${m.pairs.length===0&&m.real==='one'?'The real solution fails the nonnegative integer restrictions.':''}`;
    if(id==='tariffs')summary=`At ${p.n} uses, ${m.costA===m.costB?'both plans have equal prices':m.costA<m.costB?'A is cheaper':'B is cheaper'}. ${!m.feasibleA&&!m.feasibleB?'Neither plan is feasible.':'Also check the budget and minimum usage.'}`;
    if(id==='sampling')summary=`Synthetic data; ${p.method==='random'?'random school sample':'club-only sample'} of ${p.size}, with ${C.fmt(m.percent)}% choosing A. Seed ${p.seed}.`;
    const rows=r.rows.map(row=>row.map(authoredMath));I.register([[r.summary,summary]]);I.registerTree(r.rows,rows);return {summary,rows};
  }
  C.calculate=(id,input)=>{const r=originalCalculate(id,input);dynamic(id,r);return r;};
  C.snapshot=(id,input)=>{const s=originalSnapshot(id,input),r=originalCalculate(id,input),en=dynamic(id,r);let settings=s.settings;for(const [name,spec] of Object.entries(C.definitions[id].controls))settings=settings.replace(spec.label,I.english(spec.label));settings=authoredMath(settings);I.register([[s.settings,settings],[s.result,[en.summary,...en.rows.map(row=>row.join(': '))].join('\n')]]);return s;};
})();
